```

### Step 3: Create a new web worker

Now, let's create a new web worker that will handle the CSV download:

```bash
npx ember generate worker csv-downloader-worker
```

### Step 4: Implement the CSV downloader

In the `csv-downloader` route, we will create a button that triggers the CSV download. We will use the `Worker` API to create a new web worker that will handle the download:

```javascript
// app/routes/csv-downloader.js
import Controller from '@ember/controller';
import { Worker } from 'worker_threads';

export default class CsvDownloaderRoute extends Controller {
  csvData = [];
  worker;

  async downloadCsv() {
    this.worker = new Worker('workers/csv-downloader-worker.js');
    this.worker.on('message', (data) => {
      this.csvData = data;
    });
    this.worker.on('error', (error) => {
      console.error('Error downloading CSV:', error);
    });
    this.worker.on('exit', () => {
      this.csvData = [];
    });
    this.worker.postMessage({ action: 'download' });
  }
}
